// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer initializer;
    OracleStub oracle1;
    OracleStub oracle2;

    function setUp() public {
        c = new C();
        initializer = new Initializer();
        oracle1 = new OracleStub();
        oracle2 = new OracleStub();
    }

    function testFuzz_property(
        uint256 oracleChoice,
        uint256 maintenanceRaw,
        uint256 fundingFeeRaw,
        uint256 makerFeeRaw,
        uint256 takerFeeRaw,
        uint256 positionFeeRaw,
        uint256 makerLimitRaw
    ) public {
        // WIDE admissible domain: pick one of two real contract oracles, keep fees <= 1e18 (protocol invariant)
        address chosenOracle = oracleChoice % 2 == 0 ? address(oracle1) : address(oracle2);
        uint256 maintenance = bound(maintenanceRaw, 0, 1e18);
        uint256 fundingFee = bound(fundingFeeRaw, 0, 1e18);
        uint256 makerFee = bound(makerFeeRaw, 0, 1e18);
        uint256 takerFee = bound(takerFeeRaw, 0, 1e18);
        uint256 positionFee = bound(positionFeeRaw, 0, 1e18);
        uint256 makerLimit = bound(makerLimitRaw, 0, 1e18);

        // ProductInfo calldata: (name, symbol, PayoffDefinition(payoffType=Linear, direction=Long, data=0),
        // oracle, maintenance, fundingFee, makerFee, takerFee, positionFee, makerLimit, utilizationCurve)
        bytes memory data = abi.encodeWithSelector(
            c.initialize.selector,
            "N",
            "S",
            uint8(1),          // PayoffType.Linear (valid)
            uint8(1),          // PayoffDirection.Long (valid)
            bytes30(0),
            chosenOracle,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            int128(1e17), int128(5e17), int128(2e17), uint128(5e17) // JumpRateUtilizationCurve
        );

        // initialize must be invoked from a contract address (isContract check in __UControllerProvider__initialize)
        initializer.doCall(address(c), data);

        // GENERAL RULE: for every admissible initialization, c.oracle() returns the oracle it was initialized with
        assertTrue(address(c.oracle()) == chosenOracle, "oracle() must return the stored oracle");
    }
}

contract Initializer {
    function doCall(address target, bytes memory data) external {
        (bool ok, ) = target.call(data);
        require(ok, "init failed");
    }
}

