// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 v, int256 price) public {
        // keep the oracle version in the admissible non-bootstrap domain
        v = bound(v, 1, type(uint128).max);
        price = int256(bound(uint256(price), 1, 1e18));

        // deploy a real contract oracle so initialization's isContract check passes
        FakeOracle oracle = new FakeOracle(v, price);

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(0),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // the test contract itself has code, satisfying the controller-contract check
        c.initialize(info);

        // RULE: for any admissible oracle version v >= 1, the product's public
        // currentVersion() must expose the version reported by its configured oracle.
        // Reference: oracle() returns the real oracle -> c.currentVersion().version == v.
        // Mutant: oracle() returns address(0); the empty low-level call decodes to
        // version 0, breaking the rule for every v >= 1.
        IOracleProvider.OracleVersion memory ov = c.currentVersion();
        assertTrue(ov.version == v);
    }
}

contract FakeOracle {
    uint256 private immutable _version;
    int256 private immutable _price;

    constructor(uint256 v, int256 p) {
        _version = v;
        _price = p;
    }

    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return currentVersion();
    }

    function currentVersion() public view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: _version, timestamp: block.timestamp, price: Fixed18.wrap(_price)});
    }

    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return currentVersion();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function testFuzz_property(uint256 v, int256 p) public {
        // Fuzzed oracle version and price; the fuzzer searches the whole domain.
        Oracle oracle = new Oracle();
        oracle.set(v, p);

        Controller dummyController = new Controller();

        C.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType.Linear;
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection.Long;
        info.payoffDefinition.data = bytes30(0); // neutral linear transform, never overflows
        info.oracle = oracle;
        info.maintenance = UFixed18Lib.from(1);
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.from(1);
        info.utilizationCurve.minRate = PackedFixed18.wrap(0);
        info.utilizationCurve.maxRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetUtilization = PackedUFixed18.wrap(0);

        vm.prank(address(dummyController));
        try c.initialize(info) {
            // initialized
        } catch {
            return; // outside admissible initialization domain; skip
        }

        // General rule: for any input, the product's public currentVersion() view must
        // complete and reflect the oracle's current version. The mutant returns the zero
        // address from oracle(), so the low-level static call to a non-contract reverts.
        try c.currentVersion() returns (IOracleProvider.OracleVersion memory ov) {
            assertTrue(ov.version == v);
        } catch {
            assertTrue(false);
        }
    }
}

contract Oracle {
    uint256 public version;

    function set(uint256 v, int256 p) external {
        version = v;
        price = p;
    }

    int256 public price;

    function currentVersion() external view returns (uint256, uint256, int256) {
        return (version, block.timestamp, price);
    }

    function sync() external returns (uint256, uint256, int256) {
        return (version, block.timestamp, price);
    }

    function atVersion(uint256 v) external view returns (uint256, uint256, int256) {
        return (v, block.timestamp, price);
    }
}

