pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Admissible domain: any seed. Initialize the product from a contract caller
        // (this test contract) with a contract oracle, valid payoff definition, fees <= 1e18.
        IOracleProviderLike oracleLike = new OracleStub();

        C.PayoffDefinition memory pd;
        pd.payoffType = C.PayoffDefinitionLib.PayoffType(0);
        pd.payoffDirection = C.PayoffDefinitionLib.PayoffDirection(0);
        pd.data = bytes30(uint240(seed));

        C.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = pd;
        info.oracle = IOracleProvider(address(oracleLike));
        info.maintenance = UFixed18Lib.from(1);
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.from(1);

        // initialize() records the caller as the controller (this contract has code).
        c.initialize(info);

        // General rule: for any admissible initialization, the public oracle() getter
        // must return a live oracle contract (nonzero address with code) — the one the
        // product was configured with. The mutant returns address(0), which has no code.
        assertTrue(address(c.oracle()).code.length > 0);
    }
}

