pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 makerFee) public {
        makerFee = bound(makerFee, 0, 1e18);

        // Admissible oracle must be a contract with code.
        StubOracle oracleStub = new StubOracle();

        // Initialize the product directly with the test contract as the caller
        // (it is a contract, satisfying __UControllerProvider__initialize).
        // ProductInfo is ABI-encoded flattened (all nested tuples are static
        // except the two leading strings, so a flat abi.encode matches the
        // in-place tuple encoding of ProductInfo in calldata).
        (bool okInit, ) = address(c).call(
            abi.encodeWithSelector(
                C.initialize.selector,
                "N",                      // name
                "S",                      // symbol
                uint8(0),                  // payoffType (MINUS_ONE, valid)
                uint8(0),                  // payoffDirection (valid)
                bytes30(0),                // payoff data
                address(oracleStub),       // oracle (a contract)
                uint256(1e18),             // maintenance
                uint256(0),                // fundingFee (<= 1e18)
                makerFee,                  // makerFee (<= 1e18, fuzzed)
                uint256(0),                // takerFee
                uint256(0),                // positionFee
                uint256(1e30),             // makerLimit
                int128(1e17),              // curve minRate
                int128(2e18),              // curve maxRate
                int128(1e18),              // curve targetRate
                uint128(8e17)              // curve targetUtilization
            )
        );
        require(okInit, "initialization must succeed for admissible input");

        // General rule: for any admissible initialization, the stored oracle
        // is reported verbatim through the public oracle() getter.
        assertTrue(address(c.oracle()) == address(oracleStub));
    }
}

