// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // ABI-mirror structs for IProduct.ProductInfo (calldata-compatible)
    struct PD { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct Curve { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct Info {
        string name;
        string symbol;
        PD pd;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        Curve curve;
    }

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 rawVersion, uint256 rawPrice) public {
        uint256 version = bound(rawVersion, 1, type(uint128).max);
        // keep price nonzero and away from the fixed points of an inverse transform
        int256 price = int256(bound(rawPrice, 1e12, 1e24));
        vm.assume(price != int256(1e18) && price != -int256(1e18));

        Oracle o = new Oracle();
        o.set(version, price);

        Info memory info;
        info.name = "";
        info.symbol = "";
        info.pd = PD(1, 0, bytes30(0)); // non-identity payoff (inverse-type)
        info.oracle = address(o);
        info.maintenance = 1e18;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = 0;
        info.curve = Curve(int128(0), int128(0), int128(0), uint128(0));

        bytes4 initSel = bytes4(keccak256(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"
        ));
        (bool okInit, ) = address(c).call(abi.encodeWithSelector(initSel, info));
        assertTrue(okInit, "initialize failed");

        (, bytes memory curRet) =
            address(c).staticcall(abi.encodeWithSignature("currentVersion()"));
        (, bytes memory atRet) =
            address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", version));

        (, , int256 curPrice) = abi.decode(curRet, (uint256, uint256, int256));
        (, , int256 atPrice) = abi.decode(atRet, (uint256, uint256, int256));

        // GENERAL RULE: the transformed price seen via currentVersion must equal the
        // transformed price seen via atVersion for the same oracle version.
        assertTrue(curPrice == atPrice);
    }
}

contract Oracle {
    uint256 private v;
    int256 private p;

    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        int256 price;
    }

    function set(uint256 v_, int256 p_) external {
        v = v_;
        p = p_;
    }

    function sync() external returns (OracleVersion memory) {
        return OracleVersion(v, 0, p);
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(v, 0, p);
    }

    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(v, 0, p);
    }
}
